/// All four cases, in docs/19's order.
pub const CASES: [Case; 4] = [VER01_2D, VER01_3D, VER02_2D, VER02_3D];

#[cfg(test)]
mod tests {
    use super::*;

    /// T1 points: P1 at t = 0.25, P2 at t = 0.6.
    const P1: [f64; 3] = [0.3, 0.7, 0.2];
    const P2: [f64; 3] = [0.9, 0.15, 0.55];

    struct Fixture {
        case: Case,
        p: [f64; 3],
        t: f64,
        phi: f64,
        grad: [f64; 3],
        lap: f64,
        dphi_dt: f64,
        source: f64,
    }

    const FIXTURES: [Fixture; 8] = [
    Fixture {
        case: VER01_2D,
        p: P1,
        t: 0.25,
        phi: 1.2561125466530372,
        grad: [0.18016331823430054, 0.11231386087074649, 0.0],
        lap: -2.273014958649792,
        dphi_dt: 0.0,
        source: 0.36120238268923804,
    },
    Fixture {
        case: VER01_2D,
        p: P2,
        t: 0.6,
        phi: 1.1189915772348977,
        grad: [-0.19730492820366716, 0.14233976648935534, 0.0],
        lap: 0.07808860540479552,
        dphi_dt: 0.0,
        source: -0.11580549858029374,
    },
    Fixture {
        case: VER01_3D,
        p: P1,
        t: 0.25,
        phi: 1.3479364600510595,
        grad: [0.18016331823430054, 0.10564976723274801, 0.186986158650394],
        lap: -2.552101882124729,
        dphi_dt: 0.0,
        source: 0.4459527361403434,
    },
    Fixture {
        case: VER01_3D,
        p: P2,
        t: 0.6,
        phi: 1.271459981492143,
        grad: [-0.19730492820366716, 0.13142794313058953, 0.11216650376567266],
        lap: -0.3662002115063515,
        dphi_dt: 0.0,
        source: -0.05527155024372681,
    },
    Fixture {
        case: VER02_2D,
        p: P1,
        t: 0.25,
        phi: 1.8841688199795559,
        grad: [0.2702449773514508, 0.16847079130611972, 0.0],
        lap: -3.409522437974688,
        dphi_dt: 0.0,
        source: 0.541803574033857,
    },
    Fixture {
        case: VER02_2D,
        p: P2,
        t: 0.6,
        phi: 0.7901282039658144,
        grad: [-0.13931846470229678, 0.10050715871075662, 0.0],
        lap: 0.055138940090282966,
        dphi_dt: -2.8440310585350543,
        source: -2.925802175015411,
    },
    Fixture {
        case: VER02_3D,
        p: P1,
        t: 0.25,
        phi: 2.0219046900765894,
        grad: [0.2702449773514508, 0.15847465084912202, 0.280479237975591],
        lap: -3.828152823187094,
        dphi_dt: 0.0,
        source: 0.6689291042105151,
    },
    Fixture {
        case: VER02_3D,
        p: P2,
        t: 0.6,
        phi: 0.8977872684915718,
        grad: [-0.13931846470229678, 0.09280223977494234, 0.07920159540833739],
        lap: -0.2585766696514426,
        dphi_dt: -3.2315450362759766,
        source: -3.270572685467401,
    },
    ];

    fn assert_close(what: &str, got: f64, exp: f64) {
        let tol = 1e-12 * f64::max(1.0, f64::abs(exp));
        assert!(
            f64::abs(got - exp) <= tol,
            "{what}: got {got:e}, expected {exp:e} (tolerance {tol:e})"
        );
    }

    fn assert_rel_close(what: &str, got: f64, exp: f64, tol: f64) {
        let rel = f64::abs(got - exp) / f64::abs(exp);
        assert!(
            rel <= tol,
            "{what}: got {got:e}, expected {exp:e}, relative error {rel:e} > {tol:e}"
        );
    }

    /// T1: the closed forms against the fixture table.
    #[test]
    fn t1_point_fixtures() {
        for (i, f) in FIXTURES.iter().enumerate() {
            let c = f.case;
            assert_close(&format!("fixture {i} phi"), (c.phi)(f.p, f.t), f.phi);
            let g = (c.grad_phi)(f.p, f.t);
            for k in 0..3 {
                assert_close(&format!("fixture {i} grad[{k}]"), g[k], f.grad[k]);
            }
            assert_close(&format!("fixture {i} lap"), (c.lap_phi)(f.p, f.t), f.lap);
            assert_close(
                &format!("fixture {i} dphi_dt"),
                (c.dphi_dt)(f.p, f.t),
                f.dphi_dt,
            );
            assert_close(
                &format!("fixture {i} source"),
                c.source(f.p, f.t, c.u0, GAMMA0),
                f.source,
            );
        }
    }
    /// T2: finite differences of `phi` alone reproduce `grad_phi`,
    /// `dphi_dt`, `lap_phi` and `source` to within the FD truncation
    /// error - the derivatives are the derivatives of phi.
    #[test]
    fn t2_finite_difference_source() {
        let h1 = 1e-5;
        let h2 = 2e-4;
        for c in CASES {
            for p in [P1, P2] {
                for t in [0.25, 0.6] {
                    let mut g_fd = [0.0; 3];
                    for k in 0..c.dim {
                        let mut pp = p;
                        let mut pm = p;
                        pp[k] += h1;
                        pm[k] -= h1;
                        g_fd[k] = ((c.phi)(pp, t) - (c.phi)(pm, t)) / (2.0 * h1);
                    }
                    let mut lap_fd = 0.0;
                    for k in 0..c.dim {
                        let mut pp = p;
                        let mut pm = p;
                        pp[k] += h2;
                        pm[k] -= h2;
                        lap_fd += ((c.phi)(pp, t) - 2.0 * (c.phi)(p, t) + (c.phi)(pm, t))
                            / (h2 * h2);
                    }
                    let dt_fd = ((c.phi)(p, t + h1) - (c.phi)(p, t - h1)) / (2.0 * h1);
                    let s_fd = dt_fd + c.u0[0] * g_fd[0] + c.u0[1] * g_fd[1]
                        + c.u0[2] * g_fd[2] - c.gamma0 * lap_fd;
                    let g_ex = (c.grad_phi)(p, t);
                    let dt_ex = (c.dphi_dt)(p, t);
                    let lap_ex = (c.lap_phi)(p, t);
                    let dot_ex = c.u0[0] * g_ex[0] + c.u0[1] * g_ex[1] + c.u0[2] * g_ex[2];
                    let denom = f64::abs(dt_ex) + f64::abs(dot_ex) + c.gamma0 * f64::abs(lap_ex);
                    let rel = f64::abs(s_fd - c.source(p, t, c.u0, c.gamma0)) / denom;
                    assert!(rel < 1e-6, "{} at {p:?} t {t}: FD source off, rel {rel:e}", c.id);
                    for k in 0..3 {
                        assert!(
                            f64::abs(g_fd[k] - g_ex[k])
                                <= 1e-6 * f64::max(1.0, f64::abs(g_ex[k])),
                            "{} at {p:?} t {t}: grad[{k}] FD {} vs exact {}",
                            c.id,
                            g_fd[k],
                            g_ex[k]
                        );
                    }
                }
            }
        }
    }

    /// T3: the rule is exact to degree 7 per direction, and NOT exact at
    /// degree 8 - the proof it is the 4-point rule.
    #[test]
    fn t3_gauss_exactness() {
        let lo = [0.1, 0.2, 0.3];
        let hi = [0.35, 0.5, 0.45];
        let d3 = cell_average(|p| p[0].powi(7) * p[1].powi(7) * p[2].powi(7), lo, hi, 3);
        assert_rel_close("x^7 y^7 z^7", d3, 2.4659999903201416e-10, 1e-13);
        let d2 = cell_average(|p| p[0].powi(7) * p[1].powi(7), lo, hi, 2);
        assert_rel_close("x^7 y^7", d2, 1.8312985572143555e-7, 1e-13);
        let d8 = cell_average(|p| p[0].powi(8), lo, hi, 3);
        assert!(
            f64::abs(d8 - 3.5028728298611111e-5) / 3.5028728298611111e-5 > 1e-8,
            "cell_average exact at degree 8: the rule is not the 4-point rule"
        );
    }

    /// T4: cell averages of the cases against the fixture values.
    #[test]
    fn t4_case_cell_averages() {
        assert_rel_close("VER-01-2D source", VER01_2D.source_cell_average([0.25, 0.5, 0.0], [0.375, 0.625, 1.0], 0.0, VER01_2D.u0, GAMMA0), 0.45208029358684093, 1e-11);
        assert_rel_close("VER-01-2D phi", VER01_2D.phi_cell_average([0.25, 0.5, 0.0], [0.375, 0.625, 1.0], 0.0), 1.229513139510202, 1e-11);
        assert_rel_close("VER-02-3D source", VER02_3D.source_cell_average([0.5, 0.25, 0.75], [0.625, 0.375, 0.875], 0.3, VER02_3D.u0, GAMMA0), -0.9242683135823421, 1e-11);
        assert_rel_close("VER-02-3D phi", VER02_3D.phi_cell_average([0.5, 0.25, 0.75], [0.625, 0.375, 0.875], 0.3), 1.982714677763074, 1e-11);
    }

    /// T5: the steady cases ignore `t` outright.
    #[test]
    fn t5_steady_time_invariant() {
        for c in [VER01_2D, VER01_3D] {
            assert_eq!((c.phi)(P1, 0.0), (c.phi)(P1, 5.0), "{} ignores t", c.id);
            assert_eq!((c.dphi_dt)(P1, 0.7), 0.0, "{} dphi_dt", c.id);
        }
    }

    /// T6: CASES is the four cases in docs/19's order.
    #[test]
    fn t6_cases_order() {
        let ids = ["VER-01-2D", "VER-01-3D", "VER-02-2D", "VER-02-3D"];
        let dims = [2, 3, 2, 3];
        assert_eq!(CASES.len(), 4);
        for (i, c) in CASES.iter().enumerate() {
            assert_eq!(c.id, ids[i]);
            assert_eq!(c.dim, dims[i]);
        }
    }
}
